var _index = null;

function _buildIndex() {
    if (_index)
        return _index;
    _index = {};
    for (var i = 0; i < DATA.length; i++) {
        var e = DATA[i];
        _index[e[0]] = {
            "char": e[0],
            "name": e[1],
            "keywords": e[2],
            "category": e[3]
        };
    }
    return _index;
}

// Resolve a char to its entry; unknown chars get a generic entry.
function lookup(ch) {
    var idx = _buildIndex();
    if (idx[ch])
        return idx[ch];
    return {
        "char": ch,
        "name": "emoji",
        "keywords": "",
        "category": -1
    };
}

var _catCache = {};

// All entries of a category as objects. Cached: the Unicode section is
// large, so rebuilding it on every tab switch would stall the panel.
function byCategory(cat) {
    if (_catCache[cat])
        return _catCache[cat];
    var idx = _buildIndex();
    var out = [];
    for (var i = 0; i < DATA.length; i++) {
        if (DATA[i][3] === cat)
            out.push(idx[DATA[i][0]]);
    }
    _catCache[cat] = out;
    return out;
}

// Substring search across name + keywords. All tokens must match.
function search(query) {
    var q = (query || "").toLowerCase().trim();
    if (!q)
        return [];
    var tokens = q.split(/\s+/);
    var out = [];
    for (var i = 0; i < DATA.length && out.length < 200; i++) {
        var e = DATA[i];
        var hay = (e[1] + " " + e[2]).toLowerCase();
        var ok = true;
        for (var t = 0; t < tokens.length; t++) {
            if (hay.indexOf(tokens[t]) === -1) {
                ok = false;
                break;
            }
        }
        if (ok)
            out.push(lookup(e[0]));
    }
    return out;
}

function categoryName(cat) {
    return CATEGORIES[cat] || "";
}
